'use client';

import React, { useState } from 'react';
import { useReveal } from '../hooks/useReveal';

const faqs = [
  {
    q: '하루에 얼마나 사용하면 되나요?',
    a: '하루 15분이면 충분합니다. 아이의 집중력과 발달 단계를 고려해 최적의 학습 시간을 설계했으며, 부모님이 직접 타이머를 설정하실 수 있습니다.',
  },
  {
    q: '다른 교육 앱과 뭐가 다른가요?',
    a: '단순 영상 시청이 아닌, 뇌과학 기반의 능동적 학습 설계가 핵심입니다. 아이가 스스로 탐구하고 발견하는 구조이며, 모든 콘텐츠는 교육 전문가 자문단의 검증을 거칩니다.',
  },
  {
    q: '몇 살부터 사용할 수 있나요?',
    a: '4세부터 7세까지의 아이를 대상으로 설계되었습니다. 연령별로 두뇌 발달 단계에 맞춘 차별화된 커리큘럼이 제공됩니다.',
  },
  {
    q: '아이의 개인정보는 안전한가요?',
    a: '네, COPPA 및 GDPR-K 국제 기준을 준수합니다. 아이의 학습 데이터는 오직 학습 분석에만 활용되며 외부에 절대 공유되지 않습니다. 국내 정보보호 인증도 획득했습니다.',
  },
  {
    q: '해지는 언제든 가능한가요?',
    a: '네, 위약금 없이 언제든 해지 가능합니다. 7일 무료 체험 기간 내 해지 시 비용이 전혀 발생하지 않습니다.',
  },
  {
    q: '학원에서 도입하려면 어떻게 하나요?',
    a: 'Academy 플랜 상담을 신청해 주세요. 전담 매니저가 학원 규모와 커리큘럼에 맞는 최적의 도입 방안을 안내해 드립니다.',
  },
];

function FAQItem({ item, isOpen, onToggle }: { item: typeof faqs[0]; isOpen: boolean; onToggle: () => void }) {
  return (
    <div className="border-b border-[#E9E4DB] last:border-b-0">
      <button
        onClick={onToggle}
        className="w-full flex items-center justify-between py-6 text-left group"
      >
        <span className="text-[#2D3436] font-medium pr-8 group-hover:text-[#8C9A8B] transition-colors">
          {item.q}
        </span>
        <span className={`w-8 h-8 rounded-full border border-[#E9E4DB] flex-shrink-0 flex items-center justify-center transition-all duration-300 ${isOpen ? 'bg-[#8C9A8B] border-[#8C9A8B] rotate-45' : 'group-hover:border-[#8C9A8B]'}`}>
          <svg className={`w-4 h-4 ${isOpen ? 'text-white' : 'text-[#636E72]'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
          </svg>
        </span>
      </button>
      <div className={`overflow-hidden transition-all duration-300 ${isOpen ? 'max-h-48 pb-6' : 'max-h-0'}`}>
        <p className="text-[#636E72] leading-relaxed text-[15px] pr-12">
          {item.a}
        </p>
      </div>
    </div>
  );
}

export default function FAQ() {
  const ref = useReveal();
  const [openIdx, setOpenIdx] = useState<number | null>(0);

  return (
    <section ref={ref} className="py-28 md:py-36 px-6 lg:px-12 xl:px-20 bg-white relative">
      <div className="max-w-5xl mx-auto">
        <div className="text-center mb-16">
          <span className="reveal text-[11px] uppercase tracking-[0.3em] text-[#8C9A8B] font-medium block mb-5">
            FAQ
          </span>
          <h2 className="reveal font-serif text-3xl md:text-5xl text-[#2D3436] leading-tight mb-6">
            자주 묻는<br />
            <span className="italic font-light">질문들</span>
          </h2>
        </div>

        <div className="reveal">
          {faqs.map((faq, i) => (
            <FAQItem
              key={i}
              item={faq}
              isOpen={openIdx === i}
              onToggle={() => setOpenIdx(openIdx === i ? null : i)}
            />
          ))}
        </div>
      </div>
    </section>
  );
}
