'use client';

import React, { useState, useEffect } from 'react';

export default function Navigation() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 60);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <nav
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
        scrolled
          ? 'bg-[#FDFBF7]/90 backdrop-blur-md shadow-sm py-4'
          : 'bg-transparent py-6'
      }`}
    >
      <div className="w-full mx-auto px-6 lg:px-12 xl:px-20 flex items-center justify-between">
        <a href="#" className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-full bg-[#8C9A8B] flex items-center justify-center">
            <span className="text-white text-xs font-bold">L</span>
          </div>
          <span className={`font-serif text-lg tracking-tight transition-colors ${
            scrolled ? 'text-[#2D3436]' : 'text-[#2D3436]'
          }`}>
            Little Minds
          </span>
        </a>

        {/* Desktop */}
        <div className="hidden md:flex items-center gap-8">
          <a href="#philosophy" className="text-sm text-[#636E72] hover:text-[#2D3436] transition-colors">교육 철학</a>
          <a href="#how-it-works" className="text-sm text-[#636E72] hover:text-[#2D3436] transition-colors">학습 과정</a>
          <a href="#for-academy" className="text-sm text-[#636E72] hover:text-[#2D3436] transition-colors">학원 솔루션</a>
          <a href="#pricing" className="text-sm text-[#636E72] hover:text-[#2D3436] transition-colors">요금제</a>
          <a
            href="#final-cta"
            className="bg-[#8C9A8B] text-white px-6 py-2.5 rounded-full text-sm font-medium hover:bg-[#7a887a] transition-all"
          >
            무료 체험 시작
          </a>
        </div>

        {/* Mobile menu button */}
        <button
          onClick={() => setMenuOpen(!menuOpen)}
          className="md:hidden flex flex-col gap-1.5 p-2"
          aria-label="메뉴"
        >
          <span className={`w-5 h-0.5 bg-[#2D3436] transition-all ${menuOpen ? 'rotate-45 translate-y-2' : ''}`} />
          <span className={`w-5 h-0.5 bg-[#2D3436] transition-all ${menuOpen ? 'opacity-0' : ''}`} />
          <span className={`w-5 h-0.5 bg-[#2D3436] transition-all ${menuOpen ? '-rotate-45 -translate-y-2' : ''}`} />
        </button>
      </div>

      {/* Mobile menu */}
      {menuOpen && (
        <div className="md:hidden bg-[#FDFBF7]/95 backdrop-blur-md border-t border-[#E9E4DB] mt-2">
          <div className="px-6 py-6 flex flex-col gap-4">
            <a href="#philosophy" onClick={() => setMenuOpen(false)} className="text-[#636E72] py-2">교육 철학</a>
            <a href="#how-it-works" onClick={() => setMenuOpen(false)} className="text-[#636E72] py-2">학습 과정</a>
            <a href="#for-academy" onClick={() => setMenuOpen(false)} className="text-[#636E72] py-2">학원 솔루션</a>
            <a href="#pricing" onClick={() => setMenuOpen(false)} className="text-[#636E72] py-2">요금제</a>
            <a
              href="#final-cta"
              onClick={() => setMenuOpen(false)}
              className="bg-[#8C9A8B] text-white px-6 py-3 rounded-full text-sm font-medium text-center mt-2"
            >
              무료 체험 시작
            </a>
          </div>
        </div>
      )}
    </nav>
  );
}
